1	import { scoreArmy, type Card } from "./sphinx-score.js";
2	
3	type ArmyDocument = { army: Card[] };
4	
5	export const scoreDocument = (armyDocument: string): string => {
6	  const { army } = JSON.parse(armyDocument) as ArmyDocument;
7	  return JSON.stringify({ score: scoreArmy(army) });
8	};
