1	import { describe, it, expect } from "vitest";
2	import { scoreDocument } from "./cli.js";
3	
4	describe("Sphinx scoring CLI", () => {
5	  it('scores an input document into an output document — {"army":[]} yields {"score":0}', () => {
6	    expect(scoreDocument('{"army":[]}')).toBe('{"score":0}');
7	  });
8	  it('delegates scoring to the army rules — the spec\'s example document yields {"score":2}', () => {
9	    const document =
10	      '{"army":[{"monster":"sphinx"},{"monster":"undead-warrior","rank":2},{"monster":"hydra"}]}';
11	
12	    expect(scoreDocument(document)).toBe('{"score":2}');
13	  });
14	  it("passes Undead Warrior rank through to the scorer — variants count as one type", () => {
15	    const document =
16	      '{"army":[{"monster":"sphinx"},' +
17	      '{"monster":"undead-warrior","rank":1},' +
18	      '{"monster":"undead-warrior","rank":2},' +
19	      '{"monster":"undead-warrior","rank":3},' +
20	      '{"monster":"cyclops"},{"monster":"orthrus"},{"monster":"chimera"}]}';
21	
22	    expect(scoreDocument(document)).toBe('{"score":3}');
23	  });
